-- NOVA INDEPENDENT DE-FA COURSE V2
-- SERIES 2
-- Stage: de-fa-a1-series-0002
-- Schema: v9.0; idempotent chapter import; no schema changes.
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS import_nova_series_002$$
CREATE PROCEDURE import_nova_series_002()
BEGIN
  DECLARE v_count INT DEFAULT 0; DECLARE v_course BIGINT UNSIGNED; DECLARE v_level BIGINT UNSIGNED; DECLARE v_module BIGINT UNSIGNED; DECLARE v_chapter BIGINT UNSIGNED;
  DECLARE v_c_raha BIGINT UNSIGNED; DECLARE v_c_jonas BIGINT UNSIGNED;
  DECLARE v_l_1 BIGINT UNSIGNED;
  DECLARE v_l_2 BIGINT UNSIGNED;
  DECLARE v_l_3 BIGINT UNSIGNED;
  DECLARE v_l_4 BIGINT UNSIGNED;
  DECLARE v_t_1 BIGINT UNSIGNED;
  DECLARE v_t_2 BIGINT UNSIGNED;
  DECLARE v_t_3 BIGINT UNSIGNED;
  DECLARE v_t_4 BIGINT UNSIGNED;
  DECLARE v_t_5 BIGINT UNSIGNED;
  DECLARE v_t_6 BIGINT UNSIGNED;
  DECLARE v_t_7 BIGINT UNSIGNED;
  DECLARE v_t_8 BIGINT UNSIGNED;
  DECLARE v_w_001 BIGINT UNSIGNED;
  DECLARE v_w_002 BIGINT UNSIGNED;
  DECLARE v_w_003 BIGINT UNSIGNED;
  DECLARE v_w_004 BIGINT UNSIGNED;
  DECLARE v_w_005 BIGINT UNSIGNED;
  DECLARE v_w_006 BIGINT UNSIGNED;
  DECLARE v_w_007 BIGINT UNSIGNED;
  DECLARE v_w_008 BIGINT UNSIGNED;
  DECLARE v_w_009 BIGINT UNSIGNED;
  DECLARE v_w_010 BIGINT UNSIGNED;
  DECLARE v_w_011 BIGINT UNSIGNED;
  DECLARE v_w_012 BIGINT UNSIGNED;
  DECLARE v_w_013 BIGINT UNSIGNED;
  DECLARE v_w_014 BIGINT UNSIGNED;
  DECLARE v_w_015 BIGINT UNSIGNED;
  DECLARE v_w_016 BIGINT UNSIGNED;
  DECLARE v_w_017 BIGINT UNSIGNED;
  DECLARE v_w_018 BIGINT UNSIGNED;
  DECLARE v_w_019 BIGINT UNSIGNED;
  DECLARE v_w_020 BIGINT UNSIGNED;
  DECLARE v_w_021 BIGINT UNSIGNED;
  DECLARE v_w_022 BIGINT UNSIGNED;
  DECLARE v_w_023 BIGINT UNSIGNED;
  DECLARE v_w_024 BIGINT UNSIGNED;
  DECLARE v_w_025 BIGINT UNSIGNED;
  DECLARE v_w_026 BIGINT UNSIGNED;
  DECLARE v_w_027 BIGINT UNSIGNED;
  DECLARE v_w_028 BIGINT UNSIGNED;
  DECLARE v_w_029 BIGINT UNSIGNED;
  DECLARE v_w_030 BIGINT UNSIGNED;
  DECLARE v_w_031 BIGINT UNSIGNED;
  DECLARE v_w_032 BIGINT UNSIGNED;
  DECLARE v_w_033 BIGINT UNSIGNED;
  DECLARE v_w_034 BIGINT UNSIGNED;
  DECLARE v_w_035 BIGINT UNSIGNED;
  DECLARE v_w_036 BIGINT UNSIGNED;
  DECLARE v_w_037 BIGINT UNSIGNED;
  DECLARE v_w_038 BIGINT UNSIGNED;
  DECLARE v_w_039 BIGINT UNSIGNED;
  DECLARE v_w_040 BIGINT UNSIGNED;
  DECLARE v_w_041 BIGINT UNSIGNED;
  DECLARE v_w_042 BIGINT UNSIGNED;
  DECLARE v_w_043 BIGINT UNSIGNED;
  DECLARE v_w_044 BIGINT UNSIGNED;
  DECLARE v_w_045 BIGINT UNSIGNED;
  DECLARE v_w_046 BIGINT UNSIGNED;
  DECLARE v_w_047 BIGINT UNSIGNED;
  DECLARE v_w_048 BIGINT UNSIGNED;
  DECLARE v_w_049 BIGINT UNSIGNED;
  DECLARE v_w_050 BIGINT UNSIGNED;
  DECLARE v_w_051 BIGINT UNSIGNED;
  DECLARE v_w_052 BIGINT UNSIGNED;
  DECLARE v_w_053 BIGINT UNSIGNED;
  DECLARE v_w_054 BIGINT UNSIGNED;
  DECLARE v_w_055 BIGINT UNSIGNED;
  DECLARE v_w_056 BIGINT UNSIGNED;
  DECLARE v_w_057 BIGINT UNSIGNED;
  DECLARE v_w_058 BIGINT UNSIGNED;
  DECLARE v_w_059 BIGINT UNSIGNED;
  DECLARE v_w_060 BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='de' AND base_language='fa';
  IF v_count=0 THEN INSERT INTO courses (learning_language,base_language,title,title_translation,description,description_translation,status,metadata) VALUES ('de','fa','Deutsch für Persischsprachige','آلمانی برای فارسی‌زبانان','Independent story-first German course.','دورهٔ مستقل و داستان‌محور زبان آلمانی.','active',JSON_OBJECT('contract','independent_course_v2','storyline','berlin_new_start')); SET v_course=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa course identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_count=0 THEN INSERT INTO levels (course_id,cefr_level,title,title_translation,description,description_translation,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_course,'A1','Ankommen und erste Schritte','ورود و نخستین گام‌ها','Absolute-beginner German in a continuous Berlin story.','آلمانی مقدماتی در داستانی پیوسته در برلین.',1,2,1,'active',JSON_OBJECT('seriesStart',1,'seriesEnd',48)); SET v_level=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 level identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_count=0 THEN INSERT INTO modules (level_id,title,title_translation,description,description_translation,emoji,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_level,'Neu in Berlin','تازه‌وارد در برلین','Raha arrives, meets local people and handles her first practical needs.','رها وارد برلین می‌شود، با آدم‌های محلی آشنا می‌شود و کارهای نخستین روز را انجام می‌دهد.','🧳',1,2,1,'active',JSON_OBJECT('storylineKey','berlin_new_start')); SET v_module=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 module 1 identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata,is_active) VALUES (v_course,'Raha','female','de_fa_raha',JSON_OBJECT('role','زبان‌آموز و شخصیت اصلی','age_band','adult','locale','Teheran/Berlin'),JSON_OBJECT('storyline','berlin_new_start','independent',TRUE),1); SET v_c_raha=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Raha identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_jonas FROM characters WHERE course_id=v_course AND name='Jonas' AND gender='male';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata,is_active) VALUES (v_course,'Jonas','male','de_fa_jonas',CAST('{"age_band":"adult","locale":"Berlin","role":"رانندهٔ تاکسی محلی"}' AS JSON),JSON_OBJECT('storyline','berlin_new_start','independent',TRUE),1); SET v_c_jonas=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Jonas identity is not unique'; END IF;
  SELECT id INTO v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female';
  SELECT id INTO v_c_jonas FROM characters WHERE course_id=v_course AND name='Jonas' AND gender='male';
  SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=2;
  IF v_count=0 THEN
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_002 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'alles' AND part_of_speech='pronoun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple alles|pronoun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_004 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'Berlin' AND part_of_speech='proper_noun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple Berlin|proper_noun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_007 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'danke' AND part_of_speech='interjection'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple danke|interjection'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_009 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'das' AND part_of_speech='pronoun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple das|pronoun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_010 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'dein' AND part_of_speech='determiner'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple dein|determiner'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_012 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'dort' AND part_of_speech='adverb'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple dort|adverb'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_013 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'du' AND part_of_speech='pronoun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple du|pronoun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_014 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'ein' AND part_of_speech='article'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple ein|article'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_020 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'gut' AND part_of_speech='adjective'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple gut|adjective'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_022 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'hallo' AND part_of_speech='interjection'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple hallo|interjection'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_024 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'hier' AND part_of_speech='adverb'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple hier|adverb'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_025 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'Hilfe' AND part_of_speech='noun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple Hilfe|noun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_026 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'ich' AND part_of_speech='pronoun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple ich|pronoun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_027 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'in' AND part_of_speech='preposition'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple in|preposition'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_029 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'ja' AND part_of_speech='interjection'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple ja|interjection'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_033 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'los' AND part_of_speech='adverb'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple los|adverb'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_034 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'mein' AND part_of_speech='determiner'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple mein|determiner'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_039 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'neu' AND part_of_speech='adjective'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple neu|adjective'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_042 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'Raha' AND part_of_speech='proper_noun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple Raha|proper_noun'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_044 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'sehr' AND part_of_speech='adverb'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple sehr|adverb'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_045 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'sein' AND part_of_speech='verb'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple sein|verb'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_052 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'willkommen' AND part_of_speech='adjective'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple willkommen|adjective'; END IF;
    SELECT COUNT(*),MIN(id) INTO v_count,v_w_053 FROM words WHERE course_id=v_course AND BINARY lemma=BINARY 'wir' AND part_of_speech='pronoun'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or duplicate existing tuple wir|pronoun'; END IF;
  ELSEIF v_count=1 THEN
    SELECT id INTO v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  SELECT id INTO v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=2;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>32 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>48 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0002' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<12 OR COUNT(a.id)>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_002()$$
DROP PROCEDURE IF EXISTS import_nova_series_002$$
DELIMITER ;
